<script setup>
import { phaseLabels, eventTime } from '@/utils/event-contract'
defineProps({ event: { type: Object, required: true } })
</script>
<template><section class="event-facts"><header><h2>{{ event.title }}</h2><span class="event-phase" :class="event.phase">{{ phaseLabels[event.phase] }}</span></header><dl><dt>事件编号</dt><dd>{{ event.eventCode || event.eventId }}</dd><dt>来源设备</dt><dd>{{ event.deviceCode || event.deviceId || '未知或无权查看' }}</dd><dt>发生时间</dt><dd>{{ eventTime(event.occurredAt) }}</dd><dt>接收时间</dt><dd>{{ eventTime(event.receivedAt) }}</dd><dt>事件来源</dt><dd>{{ event.sourceSystem === 'FRONTEND_MOCK' ? '本地记录' : event.sourceSystem }} / {{ event.sourceEventId }}</dd><dt>来源更新</dt><dd>{{ eventTime(event.sourceUpdatedAt) }}{{ event.freshness === 'STALE' ? ' · 数据已过期' : '' }}</dd><template v-if="event.rawType || event.rawLevel"><dt>原始类型 / 等级</dt><dd>{{ event.rawType || '未知' }} / {{ event.rawLevel || '未知' }}</dd></template><template v-if="event.legacyHandled != null"><dt>遗留处理标记</dt><dd>{{ event.legacyHandled === 1 ? '旧端已处理' : event.legacyHandled === 0 ? '旧端未处理' : '未知' }}（不等于已核验或结案）</dd></template></dl><dl v-if="event.deviceReport"><dt>预置设备报告</dt><dd>{{ event.deviceReport.category }} · {{ event.deviceReport.model }}</dd><dt>需求来源说明</dt><dd>{{ event.deviceReport.description }}</dd><dt>恢复状态</dt><dd>未知（不随本地跟进阶段改变）</dd><dt>设备现场反馈</dt><dd>{{ event.deviceReport.localFeedback }}</dd><dt>预置记录</dt><dd>{{ event.deviceReport.evidence }}</dd></dl><p class="event-caution">设备通信异常不直接判定穿戴违规，需结合现场证据核验。</p></section></template>
